// The burst that follows a click: particles thrown outwards, and a ring that
// opens and fades under them. Driven by anime.js, which the layout loads for
// this and nothing else.
//
// Filename note: this is not minified and has not been for a while — it is
// hand-written like the rest of source/js, and the name only survives because
// layout.ejs asks for this path.
//
// Rewritten for being clicked quickly, which the version before it was not:
//
//   * It resized the canvas on every click. That reallocates the whole backing
//     store — a couple of megapixels on a dense display — and it was by far the
//     most expensive thing a click did. The canvas is sized on resize now,
//     which is the only time its size changes.
//   * It kept every burst alive until its animation ran out, so a second of
//     furious clicking meant hundreds of particles being drawn per frame, each
//     with its own fillStyle. Bursts are capped now, and the oldest gives way
//     to the newest.
//   * It ran an animation of infinite duration as its render loop, so the page
//     drew 60 times a second whether or not anything was on screen. The loop
//     runs while there are bursts and stops when the last one ends.

(function () {
    const canvas = document.getElementById("fireworks");
    if (!canvas) return;

    const ctx = canvas.getContext("2d");

    // The site's own colours, each one taken from something on the page: the
    // teal the post titles are set in, the purple the menu gradient ends on, and
    // the pink and blue the category and tag pills are filled with. Four of
    // them, which is also how many fillStyle changes a burst costs.
    const COLOURS = ["#85bac0", "#cca4e3", "#ffbbf4", "#9abbf7"];
    // Per click. It is also what the per-frame work scales with: four bursts of
    // these plus their rings is the ceiling, whatever the pointer is doing.
    const PARTICLES = 14;
    const SPREAD = 200;
    // The size of one particle, as a fraction of the root font size, against
    // the radius it starts at. It used to start at 1-2 of them, which is 32-64px
    // across: fourteen of those on one point is not a burst, it is a disc, and
    // clicking quickly stacked the discs into a mass. A third of that reads as
    // a spray instead.
    const SIZE_MIN = 0.45;
    const SIZE_MAX = 1.05;
    // How far off the click point a particle starts, again in root font sizes,
    // so the burst begins as a small cloud rather than a single stack.
    const JITTER = 0.35;
    // Particles are drawn softly and at varying strength, so that where several
    // of them land together they add up to a haze rather than to a solid.
    const ALPHA_MIN = 0.5;
    const ALPHA_MAX = 0.9;
    // How long a particle takes to reach the end of its flight. Slower than it
    // was, so the burst hangs in the air for a moment instead of being over
    // before the eye has followed it. The ring's own flash is separate — see
    // its alpha tween — and does not scale with this.
    const DURATION_MIN = 1600;
    const DURATION_MAX = 2400;

    // The ring, as a multiple of the root font size — 3 to 4 of a 16px root is
    // a radius of 48-64px. It is the loudest thing here and it started at 8.75
    // to 11.25, near enough to a circle a third of the width of the screen.
    // These two numbers are the whole of the size; the stroke is separate.
    const RING_MIN = 3;
    const RING_MAX = 4;
    const RING_WIDTH = 6;

    // How many bursts can be on screen at once. Past this the oldest is cut
    // short rather than the newest being refused: a click always answers, and
    // the work per frame stays where it is however fast the pointer is going.
    // Four bursts is a hundred shapes a frame, which is nothing.
    const MAX_BURSTS = 4;

    const bursts = [];
    let running = false;

    // The balls, one sprite per palette colour, built once at this size and
    // scaled to whatever radius a particle has at the time.
    //
    // Each one is just the colour: solid in the middle, and gone by the edge.
    // There is nothing drawn on top of it and nothing shaded into its side. What
    // makes a circle read as a sphere — a highlight, a dark side, a bright rim —
    // is also what makes it read as a button from another decade, and this page
    // has gloss nowhere else. The weight comes from the soft edge instead, which
    // is the same edge the rings behind the title and the stars are made of: a
    // body, then a short falloff, then nothing.
    //
    // Built as a sprite rather than made per particle per frame: at the four
    // bursts that can be on screen, that would be fifty-six gradients a frame
    // for four pictures.
    const BALL_SIZE = 64;

    const toRgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.substr(i, 2), 16));
    const css = (rgb, alpha) => `rgba(${rgb[0]}, ${rgb[1]}, ${rgb[2]}, ${alpha})`;

    function createBall(hex) {
        const rgb = toRgb(hex);
        const sprite = document.createElement("canvas");
        sprite.width = sprite.height = BALL_SIZE;
        const ball = sprite.getContext("2d");
        const half = BALL_SIZE / 2;

        // The stops are the shape: where the colour holds, where it starts to
        // give way, and where it is gone. Pushed out, the body is more of the
        // ball and the falloff is shorter.
        const body = ball.createRadialGradient(half, half, 0, half, half, half);
        body.addColorStop(0, css(rgb, 1));
        body.addColorStop(0.62, css(rgb, 0.95));
        body.addColorStop(0.88, css(rgb, 0.32));
        body.addColorStop(1, css(rgb, 0));
        ball.fillStyle = body;
        ball.fillRect(0, 0, BALL_SIZE, BALL_SIZE);

        return sprite;
    }

    const BALLS = COLOURS.map(createBall);

    function resize() {
        const ratio = window.devicePixelRatio || 1;
        canvas.width = window.innerWidth * ratio;
        canvas.height = window.innerHeight * ratio;
        // Draw in CSS pixels; the ratio rides on the transform, which setting
        // the canvas size has just reset.
        ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    }

    // One clearing and one pass over the bursts per frame, rather than a pass
    // and a clearing per burst.
    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        for (const burst of bursts) burst.draw();
        if (bursts.length) requestAnimationFrame(render);
        else running = false;
    }

    function start() {
        if (running) return;
        running = true;
        requestAnimationFrame(render);
    }

    function createBurst(x, y) {
        const root = parseFloat(
            getComputedStyle(document.documentElement).fontSize
        );

        // Held one array per colour, so the whole burst is four fillStyle
        // changes rather than one per particle: setting the style is what
        // costs, the filling is not.
        const byColour = COLOURS.map(() => []);
        const particles = [];
        for (let i = 0; i < PARTICLES; i++) {
            const particle = {
                x: x + anime.random(-root * JITTER, root * JITTER),
                y: y + anime.random(-root * JITTER, root * JITTER),
                radius: anime.random(root * SIZE_MIN, root * SIZE_MAX),
                toX: x + anime.random(-SPREAD, SPREAD),
                toY: y + anime.random(-SPREAD, SPREAD),
                alpha:
                    ALPHA_MIN + Math.random() * (ALPHA_MAX - ALPHA_MIN),
            };
            byColour[(Math.random() * COLOURS.length) | 0].push(particle);
            particles.push(particle);
        }

        const ring = {
            x,
            y,
            radius: 0,
            lineWidth: RING_WIDTH,
            alpha: 1,
        };

        const duration = () => anime.random(DURATION_MIN, DURATION_MAX);
        const burst = {
            draw() {
                for (let c = 0; c < byColour.length; c++) {
                    const group = byColour[c];
                    if (!group.length) continue;
                    const ball = BALLS[c];
                    for (const particle of group) {
                        if (particle.radius <= 0) continue;
                        ctx.globalAlpha = particle.alpha;
                        ctx.drawImage(
                            ball,
                            particle.x - particle.radius,
                            particle.y - particle.radius,
                            particle.radius * 2,
                            particle.radius * 2
                        );
                    }
                }
                ctx.globalAlpha = 1;
                if (ring.alpha <= 0) return;
                ctx.globalAlpha = ring.alpha;
                ctx.strokeStyle = "#fff";
                ctx.lineWidth = Math.max(ring.lineWidth, 0);
                ctx.beginPath();
                ctx.arc(ring.x, ring.y, Math.max(ring.radius, 0), 0, Math.PI * 2);
                ctx.stroke();
                ctx.globalAlpha = 1;
            },
        };

        // Two animations per burst, and the burst goes when both are done.
        let finished = 0;
        const done = () => {
            if (++finished < 2) return;
            const at = bursts.indexOf(burst);
            if (at !== -1) bursts.splice(at, 1);
        };

        burst.particleAnim = anime({
            targets: particles,
            x: (particle) => particle.toX,
            y: (particle) => particle.toY,
            radius: 0,
            duration,
            easing: "easeOutExpo",
            complete: done,
        });
        burst.ringAnim = anime({
            targets: ring,
            radius: () => anime.random(RING_MIN * root, RING_MAX * root),
            lineWidth: 0,
            alpha: { value: 0, easing: "linear", duration: () => anime.random(400, 600) },
            duration,
            easing: "easeOutExpo",
            complete: done,
        });
        return burst;
    }

    window.addEventListener("mousedown", (event) => {
        if (bursts.length >= MAX_BURSTS) {
            // Cut the oldest short. Paused rather than left running, so its
            // animations stop doing work the moment it stops being drawn.
            const oldest = bursts.shift();
            oldest.particleAnim.pause();
            oldest.ringAnim.pause();
        }
        bursts.push(createBurst(event.clientX, event.clientY));
        start();
    });

    window.addEventListener("resize", resize);
    resize();
})();
